(1872165, 258143, 45893, '<td valign="top">THATS REALLY SMART LOVE IT</td>', 'THATS REALLY SMART LOVE IT', '2005-11-16 09:02:02.000000', NULL, 1),
(1872168, 258254, 15711, '<td valign="top">Great lighting and artfully done.  BUT (this is nitpicking) if he were a scholar, wouldn''t he be looking at words, and not images?  Just a thought.  Great composition.</td>', 'Great lighting and artfully done.  BUT (this is nitpicking) if he were a scholar, wouldn''t he be looking at words, and not images?  Just a thought.  Great composition.', '2005-11-16 09:02:27.000000', NULL, 1),
(1872169, 257736, 45194, '<td valign="top">What the hell am I looking at?  I would have given it a 5 but since I had to keep going back to look at it again that must mean its above average - 6</td>', 'What the hell am I looking at?  I would have given it a 5 but since I had to keep going back to look at it again that must mean its above average - 6', '2005-11-16 09:02:30.000000', NULL, 1),
(1872172, 256755, 15711, '<td valign="top">I''m not a big fan of plastic toys in a shot, but this really works.  It''s quirky and the repetitiveness of it makes for a fun image!! 7</td>', 'I''m not a big fan of plastic toys in a shot, but this really works.  It''s quirky and the repetitiveness of it makes for a fun image!! 7', '2005-11-16 09:03:14.000000', NULL, 1),
(1872179, 257985, 15711, '<td valign="top">GREAT TITLE!  I think I''d like a bit more negative space to one side. I do like the glow of the orange though.</td>', 'GREAT TITLE!  I think I''d like a bit more negative space to one side. I do like the glow of the orange though.', '2005-11-16 09:04:31.000000', NULL, 1),
(1872182, 255871, 15711, '<td valign="top">HEE HEE - several of these doggy shots (mine included - LOL)<br/> <br/>I think the carpet and the hair on the rug is a tad distracting. Great eye and nose focus though.</td>', 'HEE HEE - several of these doggy shots (mine included - LOL) I think the carpet and the hair on the rug is a tad distracting. Great eye and nose focus though.', '2005-11-16 09:05:28.000000', NULL, 1),
(1872185, 257983, 15711, '<td valign="top">I like this alot.  Interesting perspective. Love the reflection off of the goggles.  8</td>', 'I like this alot.  Interesting perspective. Love the reflection off of the goggles.  8', '2005-11-16 09:05:52.000000', NULL, 1),
(1872189, 256783, 15711, '<td valign="top">Nice pleasant expression. I like the colored glints in the eye. Very nicely done considering the light used. 8</td>', 'Nice pleasant expression. I like the colored glints in the eye. Very nicely done considering the light used. 8', '2005-11-16 09:07:13.000000', NULL, 1),
(1872191, 258055, 15711, '<td valign="top">I like her "sunken eyes" in this.  The birthmark makes it for me.  Nicely done. 7</td>', 'I like her "sunken eyes" in this.  The birthmark makes it for me.  Nicely done. 7', '2005-11-16 09:07:53.000000', NULL, 1),
(1872194, 256249, 15711, '<td valign="top">The challenge called for artificial light. Hmmmmmmmm NOt seeing that here although the scene and silhouettes are nice.</td>', 'The challenge called for artificial light. Hmmmmmmmm NOt seeing that here although the scene and silhouettes are nice.', '2005-11-16 09:08:20.000000', NULL, 1),
(1872198, 258172, 15711, '<td valign="top">COOL!!!  Is it a dog? A wolf?  A horse. Hmmmmmmmmmmmm - very mysterious.</td>', 'COOL!!!  Is it a dog? A wolf?  A horse. Hmmmmmmmmmmmm - very mysterious.', '2005-11-16 09:09:01.000000', NULL, 1),
(1872200, 257651, 15711, '<td valign="top">I think guitar shots are over done BUT I like this one alot.  The glowing sense of it and the complementary blue/brown combination works for me.  GOOD ONE. 7</td>', 'I think guitar shots are over done BUT I like this one alot.  The glowing sense of it and the complementary blue/brown combination works for me.  GOOD ONE. 7', '2005-11-16 09:09:35.000000', NULL, 1),
(1872201, 257862, 15711, '<td valign="top">Nothin'' like a kitty with a ribbon!!!  The carpet is a tad distracting, but the overall shot is nicely achieved.  I like the whiskers!!!</td>', 'Nothin'' like a kitty with a ribbon!!!  The carpet is a tad distracting, but the overall shot is nicely achieved.  I like the whiskers!!!', '2005-11-16 09:10:14.000000', NULL, 1),
(1872204, 258219, 15711, '<td valign="top">Interesting.  I like hte solemn expression and the shadow on the moon. Well done and thoughtfully executed. 8 (ps - not a fan of the long title, just the last word would have sufficed, but that''s me)</td>', 'Interesting.  I like hte solemn expression and the shadow on the moon. Well done and thoughtfully executed. 8 (ps - not a fan of the long title, just the last word would have sufficed, but that''s me)', '2005-11-16 09:11:19.000000', NULL, 1),
