(1872209, 256870, 15711, '<td valign="top">Love the eyes.  The rub is a bit distracting.  HEE HEE - love those kitties.</td>', 'Love the eyes.  The rub is a bit distracting.  HEE HEE - love those kitties.', '2005-11-16 09:12:44.000000', NULL, 1),
(1872211, 258080, 15711, '<td valign="top">I really had to study this one. I like that I had to "work " for it.  Nicely done. Maybe if the floor weren''t so textured, but then again, maybe that adds to the intrigue. 7</td>', 'I really had to study this one. I like that I had to "work " for it.  Nicely done. Maybe if the floor weren''t so textured, but then again, maybe that adds to the intrigue. 7', '2005-11-16 09:13:35.000000', NULL, 1),
