(1872230, 257553, 15711, '<td valign="top">BEAUTIFUL. Her skin looks like porcelain. The harshness of the light works well and I love the high contrast.  9</td>', 'BEAUTIFUL. Her skin looks like porcelain. The harshness of the light works well and I love the high contrast.  9', '2005-11-16 09:20:03.000000', NULL, 1),
(1872232, 256249, 35602, '<td valign="top">Nice silouette, but I am afraid the score will be lower than the picture deserves because we were supposed to use artificial light.  This is a wonderful shot, love the sky and the light.  You did a nice job photographically.</td>', 'Nice silouette, but I am afraid the score will be lower than the picture deserves because we were supposed to use artificial light.  This is a wonderful shot, love the sky and the light.  You did a nice job photographically.', '2005-11-16 09:22:31.000000', NULL, 1),
(1872233, 257588, 15711, '<td valign="top">COOL! Very fashion-sense to it. I like the eye makeup under her eye.  FUn use of props. Great high contrast.</td>', 'COOL! Very fashion-sense to it. I like the eye makeup under her eye.  FUn use of props. Great high contrast.', '2005-11-16 09:22:52.000000', NULL, 1),
(1872235, 258190, 15711, '<td valign="top">LOVE THIS!!!  Great use of backlight.  This would make a good poster.  I think I''d crop about an inch and a half off of the right side. Just my personal taste. 7</td>', 'LOVE THIS!!!  Great use of backlight.  This would make a good poster.  I think I''d crop about an inch and a half off of the right side. Just my personal taste. 7', '2005-11-16 09:23:34.000000', NULL, 1),
