(1872758, 257861, 39158, '<td valign="top">good colors and nice composition</td>', 'good colors and nice composition', '2005-11-16 11:39:35.000000', NULL, 1),
(1872759, 257769, 44490, '<td valign="top">A candle would be a nicer match to the title, unless you want to make a much darker statement.</td>', 'A candle would be a nicer match to the title, unless you want to make a much darker statement.', '2005-11-16 11:39:48.000000', NULL, 1),
