(1872762, 257639, 5885, '<td valign="top">You subject needs to act scared, perhaps some "sweat" would have made it more convincing. Overall your lighting is good and composition works. 8</td>', 'You subject needs to act scared, perhaps some "sweat" would have made it more convincing. Overall your lighting is good and composition works. 8', '2005-11-16 11:39:58.000000', NULL, 1),
(1872763, 256405, 39158, '<td valign="top">nice capture</td>', 'nice capture', '2005-11-16 11:40:37.000000', NULL, 1),
