(1872768, 258264, 37529, '<td valign="top">Very nice dramatic lighting on this shot.</td>', 'Very nice dramatic lighting on this shot.', '2005-11-16 11:41:14.000000', NULL, 1),
(1872771, 257553, 5885, '<td valign="top">She''s lovely and your lighting and exposure are wonderful. I have a problem with that shadow that extends down her throat. Overall great image. 8</td>', 'She''s lovely and your lighting and exposure are wonderful. I have a problem with that shadow that extends down her throat. Overall great image. 8', '2005-11-16 11:41:49.000000', NULL, 1),
