(1872777, 257921, 44490, '<td valign="top">Looks like you caught the sparks from the moment of striking/lighting - adds action interest to the portrait - nice.</td>', 'Looks like you caught the sparks from the moment of striking/lighting - adds action interest to the portrait - nice.', '2005-11-16 11:42:42.000000', NULL, 1),
(1872779, 257651, 5885, '<td valign="top">Great use of color and light</td>', 'Great use of color and light', '2005-11-16 11:42:58.000000', NULL, 1),
(1872781, 258088, 37529, '<td valign="top">Good macro shot.  Crystal lear focus and the B&amp;W is a plus for this shot.</td>', 'Good macro shot.  Crystal lear focus and the B&W is a plus for this shot.', '2005-11-16 11:43:13.000000', NULL, 1),
(1872783, 256790, 40370, '<td valign="top">Like the simple title, this would have done well in IMAGE GRAIN, but works well in this challenge also, love the stubble with a hit of gray... 7</td>', 'Like the simple title, this would have done well in IMAGE GRAIN, but works well in this challenge also, love the stubble with a hit of gray... 7', '2005-11-16 11:44:00.000000', NULL, 1),
(1872785, 255788, 39158, '<td valign="top">great color</td>', 'great color', '2005-11-16 11:44:02.000000', NULL, 1),
(1872788, 258061, 39158, '<td valign="top">nice color</td>', 'nice color', '2005-11-16 11:44:17.000000', NULL, 1),
(1872791, 255745, 5885, '<td valign="top">Don''t know if the photo fits the title, but I like the photo. Good exposure.</td>', 'Don''t know if the photo fits the title, but I like the photo. Good exposure.', '2005-11-16 11:44:47.000000', NULL, 1),
(1872792, 256325, 44490, '<td valign="top">Center is nice and sharp, but right side of photo suffers from distracting softness - maybe stop down a stop or else back off with this lens, and crop to match above.</td>', 'Center is nice and sharp, but right side of photo suffers from distracting softness - maybe stop down a stop or else back off with this lens, and crop to match above.', '2005-11-16 11:45:13.000000', NULL, 1),
(1872794, 256249, 37529, '<td valign="top">Nice shot but don''t think it meets the "artifical" light requirement for the challenge.  You might be marked down on the scoring for that.</td>', 'Nice shot but don''t think it meets the "artifical" light requirement for the challenge.  You might be marked down on the scoring for that.', '2005-11-16 11:45:43.000000', NULL, 1),
(1872796, 256249, 40370, '<td valign="top">I am voting favorably for the suggested ARTIFICIAL light source, so the beautiful sunset you''ve captured here doesn''t get a high score from me ... 4</td>', 'I am voting favorably for the suggested ARTIFICIAL light source, so the beautiful sunset you''ve captured here doesn''t get a high score from me ... 4', '2005-11-16 11:46:11.000000', NULL, 1),
(1872797, 257948, 37529, '<td valign="top">Really different.  Grabs my attention.  Good shot.</td>', 'Really different.  Grabs my attention.  Good shot.', '2005-11-16 11:47:11.000000', NULL, 1),
(1872798, 256560, 5885, '<td valign="top">This is by far the best leaf photo in the challenge. I''m glad you didn''t go for transparency. The water droplets and using the vien side of the leaf was a good choice. Beautiful black and white study.</td>', 'This is by far the best leaf photo in the challenge. I''m glad you didn''t go for transparency. The water droplets and using the vien side of the leaf was a good choice. Beautiful black and white study.', '2005-11-16 11:47:11.000000', NULL, 1),
(1872799, 256774, 44490, '<td valign="top">Needs to have at least something in focus, try a tripod or bumping up ISO.</td>', 'Needs to have at least something in focus, try a tripod or bumping up ISO.', '2005-11-16 11:47:40.000000', NULL, 1),
(1872800, 257688, 40370, '<td valign="top">Great idea, I think you want a ribbon with this creative display  ... 8</td>', 'Great idea, I think you want a ribbon with this creative display  ... 8', '2005-11-16 11:48:19.000000', NULL, 1),
(1872803, 258020, 40370, '<td valign="top">Boring, out of focus, next time shine the light on an unlit candle for a better effect.</td>', 'Boring, out of focus, next time shine the light on an unlit candle for a better effect.', '2005-11-16 11:49:37.000000', NULL, 1),
(1872805, 258106, 5885, '<td valign="top">I''d give this a ten, but more attention needs to be paid attention to details, such as the wild hairs in the white space. Also, tilting her head back a little would have helped not make her nose look big. 8</td>', 'I''d give this a ten, but more attention needs to be paid attention to details, such as the wild hairs in the white space. Also, tilting her head back a little would have helped not make her nose look big. 8', '2005-11-16 11:50:08.000000', NULL, 1),
(1872807, 258057, 44490, '<td valign="top">I like the digit/hand position and overall composition.  Catchy title, also thought about "In touch" or "Keeping in touch"</td>', 'I like the digit/hand position and overall composition.  Catchy title, also thought about "In touch" or "Keeping in touch"', '2005-11-16 11:50:29.000000', NULL, 1),
(1872810, 257477, 37529, '<td valign="top">Took me a second to figure out it is a snake.  I think if the snake''s head/eyes had some additional light exposure it would have been a better shot but that''s just me.  Still a good dramatic shot.</td>', 'Took me a second to figure out it is a snake.  I think if the snake''s head/eyes had some additional light exposure it would have been a better shot but that''s just me.  Still a good dramatic shot.', '2005-11-16 11:51:10.000000', NULL, 1),
(1872812, 258074, 40370, '<td valign="top">Very pretty, love the detail of the smallest one on top ... 8</td>', 'Very pretty, love the detail of the smallest one on top ... 8', '2005-11-16 11:51:10.000000', NULL, 1),
(1872818, 257791, 5885, '<td valign="top">Beautiful shot. Needs to be cropped a little tighter to get rid of that black tiny corner in the bottom left. 8</td>', 'Beautiful shot. Needs to be cropped a little tighter to get rid of that black tiny corner in the bottom left. 8', '2005-11-16 11:52:25.000000', NULL, 1),
