(1872823, 258088, 5885, '<td valign="top">Awesome detail and DoF. May be a contender.</td>', 'Awesome detail and DoF. May be a contender.', '2005-11-16 11:53:14.000000', NULL, 1),
(1872824, 257114, 44490, '<td valign="top">Good composition, color, very effective.  Might be better to have a darker black level, then crank midtone level to get the rays that you have above.</td>', 'Good composition, color, very effective.  Might be better to have a darker black level, then crank midtone level to get the rays that you have above.', '2005-11-16 11:53:35.000000', NULL, 1),
(1872825, 258143, 37529, '<td valign="top">Interesting, looks like the light source is in the bottle but I suspect it''s in your hand.  Neat shot.</td>', 'Interesting, looks like the light source is in the bottle but I suspect it''s in your hand.  Neat shot.', '2005-11-16 11:53:44.000000', NULL, 1),
