(1874261, 258189, 47704, '<td valign="top">love the use of the dark/shadow to create this pic.  nice job.</td>', 'love the use of the dark/shadow to create this pic.  nice job.', '2005-11-16 17:39:27.000000', NULL, 1),
(1874263, 258192, 739, '<td valign="top">A bit too grainy for my taste; distracts from the smooth lines of the body.  And the black background does not appear to be completely black has me wondering if there is a reflection of the body in the upper left area.</td>', 'A bit too grainy for my taste; distracts from the smooth lines of the body.  And the black background does not appear to be completely black has me wondering if there is a reflection of the body in the upper left area.', '2005-11-16 17:39:52.000000', NULL, 1),
(1874265, 257588, 739, '<td valign="top">Net works very well.</td>', 'Net works very well.', '2005-11-16 17:40:31.000000', NULL, 1),
