(1874268, 258102, 47704, '<td valign="top">this is amazing and elegant.  i love it.</td>', 'this is amazing and elegant.  i love it.', '2005-11-16 17:40:55.000000', NULL, 1),
(1874269, 256134, 739, '<td valign="top">Sorry, I don''t find this to be of any interest.</td>', 'Sorry, I don''t find this to be of any interest.', '2005-11-16 17:41:16.000000', NULL, 1),
