(1874824, 256130, 33672, '<td valign="top">Great idea. Needs a deeper DOF or needs to be sharper.</td>', 'Great idea. Needs a deeper DOF or needs to be sharper.', '2005-11-16 20:07:27.000000', NULL, 1),
