(1880780, 257069, 35066, '<td valign="top">the lighting and reflection on this could be better.. but good luck in the challenge!</td>', 'the lighting and reflection on this could be better.. but good luck in the challenge!', '2005-11-18 17:16:49.000000', NULL, 1),
