(1888374, 256776, 15643, '<td valign="top">I think a lighting that was a little less "harsh" would have been better. Maybe a soft yellow tint.</td>', 'I think a lighting that was a little less "harsh" would have been better. Maybe a soft yellow tint.', '2005-11-21 21:45:34.000000', NULL, 1),
(1888376, 258087, 15643, '<td valign="top">Now im confused...</td>', 'Now im confused...', '2005-11-21 21:45:54.000000', NULL, 1),
