(1888381, 256778, 15643, '<td valign="top">Very unique.</td>', 'Very unique.', '2005-11-21 21:48:18.000000', NULL, 1),
(1888383, 258050, 15643, '<td valign="top">This is a great image, that would have looked better cropped.</td>', 'This is a great image, that would have looked better cropped.', '2005-11-21 21:49:07.000000', NULL, 1),
