(1888394, 258189, 15643, '<td valign="top">I like the facial expression!</td>', 'I like the facial expression!', '2005-11-21 21:51:23.000000', NULL, 1),
(1888395, 257495, 15643, '<td valign="top">Somehow this picture looks a little on the blurred side, but very funny!</td>', 'Somehow this picture looks a little on the blurred side, but very funny!', '2005-11-21 21:52:06.000000', NULL, 1),
(1888397, 257282, 15643, '<td valign="top">The specs on the glass draw away from the picture, but i like the way the light shines throught the lemon.</td>', 'The specs on the glass draw away from the picture, but i like the way the light shines throught the lemon.', '2005-11-21 21:53:09.000000', NULL, 1),
(1888404, 256762, 47508, '<td valign="top">very cute!</td>', 'very cute!', '2005-11-21 21:54:36.000000', NULL, 1),
(1888408, 257491, 15643, '<td valign="top">I like this! IT is very cool idea! but the hand looks a bit too washed out, maybe a faster shutter.</td>', 'I like this! IT is very cool idea! but the hand looks a bit too washed out, maybe a faster shutter.', '2005-11-21 21:55:29.000000', NULL, 1),
(1888515, 258024, 19936, '<td valign="top">Yikes! The  ..... ah ... light is beautiful.</td>', 'Yikes! The  ..... ah ... light is beautiful.', '2005-11-21 22:49:22.000000', NULL, 1),
(1888524, 258190, 40344, '<td valign="top">I love it, well done.</td>', 'I love it, well done.', '2005-11-21 22:55:08.000000', NULL, 1),
(1888533, 257688, 40344, '<td valign="top">Very clever idea. I would like to see the darkarea at the top lightened a little.</td>', 'Very clever idea. I would like to see the darkarea at the top lightened a little.', '2005-11-21 22:57:43.000000', NULL, 1),
(1888553, 258102, 40344, '<td valign="top">Good composition and the simplicity of the subject is compelling.  Lovely image Congrats!</td>', 'Good composition and the simplicity of the subject is compelling.  Lovely image Congrats!', '2005-11-21 23:02:53.000000', NULL, 1),
(1888578, 257590, 42826, '<td valign="top">wow, some of those look like condoms for a sec...I was kinda scared...</td>', 'wow, some of those look like condoms for a sec...I was kinda scared...', '2005-11-21 23:18:48.000000', NULL, 1),
(1888579, 258211, 42826, '<td valign="top">Is this natural light?</td>', 'Is this natural light?', '2005-11-21 23:19:37.000000', NULL, 1),
(1888582, 257680, 42826, '<td valign="top">I am sure you have heard it...I have gotten the same comments...the sun in not artificial light...</td>', 'I am sure you have heard it...I have gotten the same comments...the sun in not artificial light...', '2005-11-21 23:21:15.000000', NULL, 1),
(1888584, 257963, 42826, '<td valign="top">I am sure you have heard it before...the sun is not artificial light...but I still love the sun right in the corner...nice touch.</td>', 'I am sure you have heard it before...the sun is not artificial light...but I still love the sun right in the corner...nice touch.', '2005-11-21 23:22:19.000000', NULL, 1),
(1888598, 257329, 48414, '<td valign="top">nice, so dramatic...</td>', 'nice, so dramatic...', '2005-11-21 23:38:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1888614, 258056, 30588, '<td valign="top">I really like this photo, but I think you could have cropped the bottom differetly. Higher because her nose is already really long and cropping where you did probably made it look twice as long.</td>', 'I really like this photo, but I think you could have cropped the bottom differetly. Higher because her nose is already really long and cropping where you did probably made it look twice as long.', '2005-11-21 23:49:15.000000', NULL, 1),
(1888622, 257688, 48414, '<td valign="top">awsome photograph!!! congratulations...M.C. Escher it´s proud and happy...(wherever he is) l.o.l...definitive a blue one</td>', 'awsome photograph!!! congratulations...M.C. Escher it´s proud and happy...(wherever he is) l.o.l...definitive a blue one', '2005-11-21 23:56:31.000000', NULL, 1),
(1888687, 258056, 3419, '<td valign="top">Hmmm - great photo, but it looks to me as if more than one light source has been used - flash straight on, and a light to the left side (reflecting off her nose). Wonderful photo though</td>', 'Hmmm - great photo, but it looks to me as if more than one light source has been used - flash straight on, and a light to the left side (reflecting off her nose). Wonderful photo though', '2005-11-22 00:36:51.000000', NULL, 1),
(1888703, 258112, 3419, '<td valign="top">Wonderfully executed - great sillhouette, drips off chin, and color in the drink. I imagine this was a challenge to capture to your satisfaction.</td>', 'Wonderfully executed - great sillhouette, drips off chin, and color in the drink. I imagine this was a challenge to capture to your satisfaction.', '2005-11-22 00:43:17.000000', NULL, 1),
(1888711, 258097, 3419, '<td valign="top">Love the colors in the vase. Nice lighting setup behind the vase, but this would be nicer for me if I could see some detail in the flower too.</td>', 'Love the colors in the vase. Nice lighting setup behind the vase, but this would be nicer for me if I could see some detail in the flower too.', '2005-11-22 00:47:05.000000', NULL, 1),
(1888716, 256850, 3419, '<td valign="top">Lighting is a little too harsh on the pearls in foreground (blown out), and on the rose. Color processing has flattened the red in the rose. Nice setup, but softer lighting would improve this for me.</td>', 'Lighting is a little too harsh on the pearls in foreground (blown out), and on the rose. Color processing has flattened the red in the rose. Nice setup, but softer lighting would improve this for me.', '2005-11-22 00:48:41.000000', NULL, 1),
(1888718, 258132, 3419, '<td valign="top">More contrast would improve this image.</td>', 'More contrast would improve this image.', '2005-11-22 00:49:35.000000', NULL, 1),
(1888719, 256710, 3419, '<td valign="top">So cute. Good lighting and setup. Nice capture of detail.</td>', 'So cute. Good lighting and setup. Nice capture of detail.', '2005-11-22 00:50:23.000000', NULL, 1),
(1888720, 257729, 3419, '<td valign="top">Ooooo, nicely captured! So graceful!</td>', 'Ooooo, nicely captured! So graceful!', '2005-11-22 00:50:45.000000', NULL, 1),
(1888721, 258102, 3419, '<td valign="top">Nicely lit and captured. Very classic looking.</td>', 'Nicely lit and captured. Very classic looking.', '2005-11-22 00:51:10.000000', NULL, 1),
(1888723, 256249, 3419, '<td valign="top">Not an artificial light source, so does not meet the challenge. Very nice scene though. Nicely captured, but still does not meet the challenge.</td>', 'Not an artificial light source, so does not meet the challenge. Very nice scene though. Nicely captured, but still does not meet the challenge.', '2005-11-22 00:52:05.000000', NULL, 1),
(1888724, 257631, 3419, '<td valign="top">Nice play on words - I love words play! Nice setup and execution.</td>', 'Nice play on words - I love words play! Nice setup and execution.', '2005-11-22 00:53:11.000000', NULL, 1),
(1888734, 257124, 3419, '<td valign="top">Very dramatic, and beautiful!</td>', 'Very dramatic, and beautiful!', '2005-11-22 01:04:23.000000', NULL, 1),
(1888795, 258000, 46056, '<td valign="top">SINGLE Light Source?   Attractive picture but it doesn''t meet the challenge for me, I''m afraid.</td>', 'SINGLE Light Source?   Attractive picture but it doesn''t meet the challenge for me, I''m afraid.', '2005-11-22 02:26:45.000000', NULL, 1),
(1888800, 257553, 46056, '<td valign="top">A lovely pose - very wistful.  Perhaps a little flat for my taste (slightly too harsh lighting) but only slightly.  An attractive portrait and fits the challenge well.</td>', 'A lovely pose - very wistful.  Perhaps a little flat for my taste (slightly too harsh lighting) but only slightly.  An attractive portrait and fits the challenge well.', '2005-11-22 02:35:44.000000', NULL, 1),
(1888801, 256610, 46056, '<td valign="top">Good portrait.  A little noisy on the left-hand side.  For me the crop is a little tight at the top.  Nice, though.</td>', 'Good portrait.  A little noisy on the left-hand side.  For me the crop is a little tight at the top.  Nice, though.', '2005-11-22 02:37:25.000000', NULL, 1),
(1888805, 257789, 46056, '<td valign="top">A gorgeous photograph.  I don''t even want to try to find any fault with this shot.  The ''best in challenge'' by far.</td>', 'A gorgeous photograph.  I don''t even want to try to find any fault with this shot.  The ''best in challenge'' by far.', '2005-11-22 02:40:34.000000', NULL, 1),
(1888807, 258223, 46056, '<td valign="top">Definitely caught my attention.  I would have rather had a much tighter crop top and bottom, though - I think it would have had more impact.  Certainly fits the challenge.</td>', 'Definitely caught my attention.  I would have rather had a much tighter crop top and bottom, though - I think it would have had more impact.  Certainly fits the challenge.', '2005-11-22 02:44:14.000000', NULL, 1),
(1888812, 258189, 46056, '<td valign="top">Intriguing pose.  I would have liked to see more of his right eye but this might be difficult with a single light source, I admit.</td>', 'Intriguing pose.  I would have liked to see more of his right eye but this might be difficult with a single light source, I admit.', '2005-11-22 02:48:36.000000', NULL, 1),
(1888814, 257642, 46056, '<td valign="top">There are few strong shots in this challenge (in my humble opinion).  This is one of the of the few.  Good luck.</td>', 'There are few strong shots in this challenge (in my humble opinion).  This is one of the of the few.  Good luck.', '2005-11-22 02:53:15.000000', NULL, 1),
(1888815, 257637, 29474, '<td valign="top">Pity about the cat in the background. It is a bit distracting.</td>', 'Pity about the cat in the background. It is a bit distracting.', '2005-11-22 02:55:10.000000', NULL, 1),
(1888817, 258079, 46056, '<td valign="top">Cute idea.  Perhaps not the most flattering angle, though, for a portrait?  To sell the title better, I think a classic ''dressed in white with a pretty smile'' would have worked a little better.  =;-)</td>', 'Cute idea.  Perhaps not the most flattering angle, though, for a portrait?  To sell the title better, I think a classic ''dressed in white with a pretty smile'' would have worked a little better.  =;-)', '2005-11-22 02:56:15.000000', NULL, 1),
(1888819, 257688, 46056, '<td valign="top">The idea is really clever.  Maybe if you had waited for a less restrictive challenge you could have taken the absolute best shot.  Maybe the ''single light source'' limited your options a little.  Still a great shot, though.</td>', 'The idea is really clever.  Maybe if you had waited for a less restrictive challenge you could have taken the absolute best shot.  Maybe the ''single light source'' limited your options a little.  Still a great shot, though.', '2005-11-22 02:57:52.000000', NULL, 1),
(1888824, 258050, 46056, '<td valign="top">I love the effect below the glass.  The left-hand side is a little distracting, though.  I would have cropped an inch above the glass rim and cut the left-hand side where the darker shadows come in.</td>', 'I love the effect below the glass.  The left-hand side is a little distracting, though.  I would have cropped an inch above the glass rim and cut the left-hand side where the darker shadows come in.', '2005-11-22 03:02:50.000000', NULL, 1),
(1888837, 256243, 29474, '<td valign="top">I don''t know what the white thing in front of the nose is, but it is very distracting, to the point of destroying a very good photograph.</td>', 'I don''t know what the white thing in front of the nose is, but it is very distracting, to the point of destroying a very good photograph.', '2005-11-22 03:58:57.000000', NULL, 1),
(1888882, 258252, 42436, '<td valign="top">excellent thought ... and beautiful execution<br/>you remind me of that saying<br/>there are 2 kinda photografers;<br/>those who think and make a shot<br/>and the others who shoot and make the others think...<br/>youre one of them .... 8</td>', 'excellent thought ... and beautiful executionyou remind me of that sayingthere are 2 kinda photografers;those who think and make a shotand the others who shoot and make the others think...youre one of them .... 8', '2005-11-22 05:19:47.000000', NULL, 1),
(1888891, 256760, 29474, '<td valign="top">This would have been much stronger if the pan had been perfectly clean and shiny.</td>', 'This would have been much stronger if the pan had been perfectly clean and shiny.', '2005-11-22 06:00:03.000000', NULL, 1),
(1888892, 256704, 29474, '<td valign="top">The eyes are a bit haunting. What light did you use?</td>', 'The eyes are a bit haunting. What light did you use?', '2005-11-22 06:01:02.000000', NULL, 1),
(1888893, 257789, 29474, '<td valign="top">Absolutely superb. Only nit-pick is that the dolls nappy is over-exposed.</td>', 'Absolutely superb. Only nit-pick is that the dolls nappy is over-exposed.', '2005-11-22 06:02:37.000000', NULL, 1),
(1888895, 258182, 29474, '<td valign="top">Strong picture. And the grain works very well. Could see this hanging in an upmarket restuarant.</td>', 'Strong picture. And the grain works very well. Could see this hanging in an upmarket restuarant.', '2005-11-22 06:03:36.000000', NULL, 1),
(1888897, 258189, 29474, '<td valign="top">Very good portrait with a different pose.</td>', 'Very good portrait with a different pose.', '2005-11-22 06:04:27.000000', NULL, 1),
(1888898, 256710, 29474, '<td valign="top">Clever idea well executed. Even the little bit of whit behind the door is not distracting.</td>', 'Clever idea well executed. Even the little bit of whit behind the door is not distracting.', '2005-11-22 06:05:37.000000', NULL, 1),
(1888900, 258025, 29474, '<td valign="top">This needs another object for the light to reflect off; or a whole pile of smoke. As it is now it is a mass of ill-defined red lines.</td>', 'This needs another object for the light to reflect off; or a whole pile of smoke. As it is now it is a mass of ill-defined red lines.', '2005-11-22 06:11:39.000000', NULL, 1),
(1888903, 255803, 29474, '<td valign="top">Good lighting. Simple composition.</td>', 'Good lighting. Simple composition.', '2005-11-22 06:13:32.000000', NULL, 1),
(1888904, 257997, 29474, '<td valign="top">I wonder whether this is the best angle? Portraits taken from below don''t usually flatter the subject. Maybe this applies to sculture too?</td>', 'I wonder whether this is the best angle? Portraits taken from below don''t usually flatter the subject. Maybe this applies to sculture too?', '2005-11-22 06:15:06.000000', NULL, 1),
(1888905, 256216, 29474, '<td valign="top">I would like to have seen more of the knife with more of it in focus.</td>', 'I would like to have seen more of the knife with more of it in focus.', '2005-11-22 06:18:12.000000', NULL, 1),
(1888909, 258022, 29474, '<td valign="top">I had the mouse cursor hovering over ''1'' for a moment. Great picture. And luckily the square edge of the pot gives it away.</td>', 'I had the mouse cursor hovering over ''1'' for a moment. Great picture. And luckily the square edge of the pot gives it away.', '2005-11-22 06:31:33.000000', NULL, 1),
(1888910, 255663, 29474, '<td valign="top">Good picture. Not sure of the title. There is not much of a back alley. Not that it really makes a difference.</td>', 'Good picture. Not sure of the title. There is not much of a back alley. Not that it really makes a difference.', '2005-11-22 06:35:14.000000', NULL, 1),
(1888948, 256243, 46758, '<td valign="top">In my opinion, that thing (Can''t see what it is) in front of the nose is ruining this picture that I would find good otherwise.</td>', 'In my opinion, that thing (Can''t see what it is) in front of the nose is ruining this picture that I would find good otherwise.', '2005-11-22 07:39:37.000000', NULL, 1),
(1888954, 256778, 30123, '<td valign="top">Truly Wild...</td>', 'Truly Wild...', '2005-11-22 07:47:01.000000', NULL, 1),
(1888977, 256287, 48289, '<td valign="top">VERY GOOD</td>', 'VERY GOOD', '2005-11-22 08:12:49.000000', NULL, 1),
