(1889025, 257183, 33732, '<td valign="top">Very nice.</td>', 'Very nice.', '2005-11-22 08:39:37.000000', NULL, 1),
(1889050, 258244, 33732, '<td valign="top">Interesting. There must have been other lighting around.</td>', 'Interesting. There must have been other lighting around.', '2005-11-22 08:53:16.000000', NULL, 1),
(1889051, 257791, 33732, '<td valign="top">Shadows are nice.</td>', 'Shadows are nice.', '2005-11-22 08:53:37.000000', NULL, 1),
(1889098, 256710, 42100, '<td valign="top">Great photo, very imaginative.  Definately my favorite of the challenge.</td>', 'Great photo, very imaginative.  Definately my favorite of the challenge.', '2005-11-22 09:22:03.000000', NULL, 1),
(1889101, 258204, 42100, '<td valign="top">Excellent capture.  The lighting and mood of this photo are great.</td>', 'Excellent capture.  The lighting and mood of this photo are great.', '2005-11-22 09:23:06.000000', NULL, 1),
(1889105, 255871, 42100, '<td valign="top">Cute dog.  Photo seems exposed for the carpet instead of dog.</td>', 'Cute dog.  Photo seems exposed for the carpet instead of dog.', '2005-11-22 09:25:59.000000', NULL, 1),
(1889108, 255687, 42100, '<td valign="top">Lighting emphasis is on the background, seems like it should be on the model.</td>', 'Lighting emphasis is on the background, seems like it should be on the model.', '2005-11-22 09:28:12.000000', NULL, 1),
(1889162, 257749, 42567, '<td valign="top">very pretty..!</td>', 'very pretty..!', '2005-11-22 10:13:52.000000', NULL, 1),
(1889163, 256560, 42567, '<td valign="top">very nice..!!</td>', 'very nice..!!', '2005-11-22 10:14:04.000000', NULL, 1),
(1889256, 257306, 48423, '<td valign="top">surreal yet vibrant , simple yet beautiful</td>', 'surreal yet vibrant , simple yet beautiful', '2005-11-22 11:11:35.000000', NULL, 1),
(1889275, 258025, 33732, '<td valign="top">Some reflections.  Skips in the beam are interesting.  The photo shows what the eye misses in the radiation.</td>', 'Some reflections.  Skips in the beam are interesting.  The photo shows what the eye misses in the radiation.', '2005-11-22 11:18:28.000000', NULL, 1),
(1889299, 256850, 33732, '<td valign="top">Just does not have a depth. Shadows would help.</td>', 'Just does not have a depth. Shadows would help.', '2005-11-22 11:30:33.000000', NULL, 1),
(1889302, 257921, 33732, '<td valign="top">Nice point source.  I thought they wanted some type of electrical lighting, or something like it.</td>', 'Nice point source.  I thought they wanted some type of electrical lighting, or something like it.', '2005-11-22 11:31:45.000000', NULL, 1),
(1889307, 257845, 33732, '<td valign="top">I can see the reflection of a light.  The double is interesting.</td>', 'I can see the reflection of a light.  The double is interesting.', '2005-11-22 11:33:08.000000', NULL, 1),
(1889309, 256610, 33732, '<td valign="top">There seems to be light from more than one direction.</td>', 'There seems to be light from more than one direction.', '2005-11-22 11:34:18.000000', NULL, 1),
(1889314, 257749, 33732, '<td valign="top">The light shows up well on this side of the flower. Interesting.</td>', 'The light shows up well on this side of the flower. Interesting.', '2005-11-22 11:39:40.000000', NULL, 1),
(1889327, 257194, 33732, '<td valign="top">Seems the red beams just touch the ice.</td>', 'Seems the red beams just touch the ice.', '2005-11-22 11:44:02.000000', NULL, 1),
(1889340, 257688, 8643, '<td valign="top">Very clever idea, nicely executed.</td>', 'Very clever idea, nicely executed.', '2005-11-22 11:48:10.000000', NULL, 1),
(1889345, 256760, 8643, '<td valign="top">Made me smile.  The background is a bit distracting.</td>', 'Made me smile.  The background is a bit distracting.', '2005-11-22 11:51:43.000000', NULL, 1),
(1889353, 257983, 33732, '<td valign="top">Dramatic. Just not with shadows.</td>', 'Dramatic. Just not with shadows.', '2005-11-22 11:54:29.000000', NULL, 1),
(1889355, 257120, 33732, '<td valign="top">Enjoy.  Looks inviting. Nice uplight effect and there is more than a profile.</td>', 'Enjoy.  Looks inviting. Nice uplight effect and there is more than a profile.', '2005-11-22 11:54:54.000000', NULL, 1),
(1889357, 258192, 33732, '<td valign="top">Fuzzy.</td>', 'Fuzzy.', '2005-11-22 11:55:16.000000', NULL, 1),
(1889358, 256397, 33732, '<td valign="top">That mist is interesting.</td>', 'That mist is interesting.', '2005-11-22 11:55:54.000000', NULL, 1),
