(1889363, 257727, 33732, '<td valign="top">Exposure is good. So many shells?</td>', 'Exposure is good. So many shells?', '2005-11-22 11:57:01.000000', NULL, 1),
(1889367, 258190, 33732, '<td valign="top">Interesting what the hair does under this condition.  Exposure must have been tricky.</td>', 'Interesting what the hair does under this condition.  Exposure must have been tricky.', '2005-11-22 11:58:12.000000', NULL, 1),
(1889371, 258154, 33732, '<td valign="top">Better DOF would make this better but a shadow would help the impact.</td>', 'Better DOF would make this better but a shadow would help the impact.', '2005-11-22 11:59:18.000000', NULL, 1),
(1889374, 257553, 33732, '<td valign="top">Backdrop could be better. Not a lot of shadow.</td>', 'Backdrop could be better. Not a lot of shadow.', '2005-11-22 11:59:32.000000', NULL, 1),
(1889375, 257280, 33732, '<td valign="top">Why cut off the top?</td>', 'Why cut off the top?', '2005-11-22 12:00:10.000000', NULL, 1),
(1889378, 257989, 33732, '<td valign="top">Cool flame.</td>', 'Cool flame.', '2005-11-22 12:00:48.000000', NULL, 1),
(1889380, 256187, 33732, '<td valign="top">The line?</td>', 'The line?', '2005-11-22 12:02:44.000000', NULL, 1),
