(1889386, 256287, 33732, '<td valign="top">Water effect is interesting.</td>', 'Water effect is interesting.', '2005-11-22 12:04:05.000000', NULL, 1),
(1889387, 256130, 33732, '<td valign="top">The light is diffuse so the shadow is not dramatic.</td>', 'The light is diffuse so the shadow is not dramatic.', '2005-11-22 12:04:51.000000', NULL, 1),
(1889388, 257120, 8643, '<td valign="top">I like this - just an outline, well controlled.</td>', 'I like this - just an outline, well controlled.', '2005-11-22 12:05:19.000000', NULL, 1),
(1889392, 257677, 33732, '<td valign="top">Nice patterns. Somewhat 3D.</td>', 'Nice patterns. Somewhat 3D.', '2005-11-22 12:06:07.000000', NULL, 1),
(1889393, 258204, 33732, '<td valign="top">Seems like the light was all around.  Very nice subject.</td>', 'Seems like the light was all around.  Very nice subject.', '2005-11-22 12:07:32.000000', NULL, 1),
